skill_integration_spec.cooking_loss_calc_pseudo:
// 伪代码：agent 计算单食材单营养素烹饪后值
for each ingredient:
  table = method == 'boil' ? (retain_broth ? boil.retention_broth_retained : boil.retention_broth_discarded) : method_table
  override = ingredient_overrides.get(ingredient.category + '_' + method)
  for each nutrient:
    rf = override[nutrient]?.retention_factor ?? table[nutrient].retention_factor
    adjusted_dm = raw_dm_value * rf
    adjusted_as_fed = adjusted_dm * (1 - moisture_pct/100)
